/**
 * Placeholders de carregamento no formato do conteúdo real, para a interface não
 * pular quando os dados chegam. Cada função espelha uma tela: mudou o layout lá,
 * mude aqui.
 */

/** Repete o builder `count` vezes, com key. */
function repeat(count, build) {
  return Array.from({
    length: count
  }, (_, index) => build(index));
}

/**
 * Larguras variam por linha; derivadas do índice, não aleatórias, para ficarem
 * estáveis entre redraws.
 */
function width(index, steps) {
  return steps[index % steps.length] + '%';
}

// ── Stream de mensagens ──

/** Streams de canal, thread e fixadas. */
export function MessageStreamSkeleton(rows) {
  if (rows === void 0) {
    rows = 6;
  }
  return m("div", {
    className: "ChatSkeleton",
    "aria-hidden": "true"
  }, repeat(rows, i => m("div", {
    className: "ChatSkeleton-row",
    key: i
  }, m("div", {
    className: "ChatSkeleton-avatar"
  }), m("div", {
    className: "ChatSkeleton-lines"
  }, m("div", {
    className: "ChatSkeleton-line",
    style: {
      width: width(i, [22, 30, 26])
    }
  }), m("div", {
    className: "ChatSkeleton-line",
    style: {
      width: width(i, [70, 45, 85, 55])
    }
  })))));
}

